41	const PROCESSING_FEE = 5;
42	
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
45	const LOYALTY_DISCOUNT = -0.2;
46	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
47	/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
48	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
49	
50	/** The MHPCO price list; only the types pinned down by tests so far. */
51	const BASE_PREMIUMS: Record<string, number | undefined> = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	  moonstone: 25,
58	};
59	
60	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
61	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
62	
63	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
64	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
65	
66	const basePremiumFor = (item: Item): number => {
67	  const basePremium = BASE_PREMIUMS[item.type];
68	  if (basePremium === undefined) throw new Error(`Unknown item type: ${item.type}`);
69	  return basePremium;
70	};
71	
72	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
73	  values.reduce((total, value) => total + amountOf(value), 0);
74	
75	/** A building block of 3 alike components is offered at a special base premium. */
76	const BLOCK_SIZE = 3;
77	const BLOCK_BASE_PREMIUM = 60;
78	
79	const alikeComponentGroups = (items: Item[]): Item[][] => [
80	  ...items
81	    .reduce(
82	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
83	      new Map<string, Item[]>(),
84	    )
85	    .values(),
86	];
87	
88	const basePremiumForGroup = (group: Item[]): number =>
89	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOf(group, basePremiumFor);
90	
91	const HIGH_ENCHANTMENT_THRESHOLD = 5;
92	
93	const isCursed = (item: Item): boolean => item.cursed === true;
94	
95	const isHighlyEnchanted = (item: Item): boolean =>
96	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;
97	
98	/**
99	 * A modifier raises or lowers the amount it applies to by `rate`, but only for
100	 * subjects it applies to. Modifiers that apply stack additively.
101	 */
102	interface Modifier<Subject> {
103	  appliesTo: (subject: Subject) => boolean;
104	  rate: number;
105	}
106	
107	const combinedRateOf = <Subject>(
108	  modifiers: Modifier<Subject>[],
109	  subject: Subject,
110	): number => sumOf(modifiers, ({ appliesTo, rate }) => (appliesTo(subject) ? rate : 0));
111	
112	/** Item-specific modifiers are levied on the affected item's own base premium. */
113	const ITEM_MODIFIERS: Modifier<Item>[] = [
114	  { appliesTo: isCursed, rate: CURSE_SURCHARGE },
115	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
116	];
117	
118	const modifiersFor = (item: Item): number =>
119	  basePremiumFor(item) * combinedRateOf(ITEM_MODIFIERS, item);
120	
121	const LOYALTY_THRESHOLD_YEARS = 2;
122	
123	/** The customer as they stand at the moment a particular contract is quoted. */
124	interface Policyholder {
125	  customer: Customer;
126	  isFollowUpContract: boolean;
127	}
128	
129	const isLongStanding = ({ customer }: Policyholder): boolean =>
130	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
131	
132	const isFollowUpContract = (policyholder: Policyholder): boolean =>
133	  policyholder.isFollowUpContract;
134	
135	const alwaysApplies = (): boolean => true;
136	
137	/** Policy-wide modifiers are levied on the whole policy's base premium. */
138	const POLICY_MODIFIERS: Modifier<Policyholder>[] = [
139	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT },
140	  { appliesTo: alwaysApplies, rate: INITIAL_ASSESSMENT_SURCHARGE },
141	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT },
142	];
143	
144	const quote = (step: QuoteStep, policyholder: Policyholder): StepResult => {
145	  const basePremium = sumOf(alikeComponentGroups(step.items), basePremiumForGroup);
146	  const itemModifiers = sumOf(step.items, modifiersFor);
147	  const policyBasePremium = basePremium + itemModifiers;
148	  const afterPolicyModifiers =
149	    policyBasePremium * (1 + combinedRateOf(POLICY_MODIFIERS, policyholder));
150	  return { premium: roundUpToWholeG(afterPolicyModifiers + PROCESSING_FEE) };
151	};
152	
153	const runStep = (step: Step, policyholder: Policyholder): StepResult => {
154	  if (step.op === "quote") return quote(step, policyholder);
155	  throw new Error(`Unsupported step: ${step.op}`);
156	};
157	
158	export const runScenario = (scenario: Scenario): ScenarioResult => {
159	  let contractsSoFar = 0;
160	  const results = scenario.steps.map((step) => {
161	    const result = runStep(step, {
162	      customer: scenario.customer,
163	      isFollowUpContract: contractsSoFar > 0,
164	    });
165	    if (step.op === "quote") contractsSoFar += 1;
166	    return result;
167	  });
168	  return { results };
169	};
