/**
 * Steps are not independent: a quote's premium depends on whether an earlier
 * quote already established a contract. Each step is therefore run against the
 * history left behind by the steps before it, and leaves its own mark in turn.
 */
interface ScenarioHistory {
  hasQuoted: boolean;
}

const NO_HISTORY: ScenarioHistory = { hasQuoted: false };

const historyAfter = (step: Step, history: ScenarioHistory): ScenarioHistory =>
  step.op === "quote" ? { hasQuoted: true } : history;

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const { results } = scenario.steps.reduce<{
