/**
 * Steps are not independent: a quote's premium depends on whether an earlier
 * quote in the same scenario already established a contract, so each step is
 * run against the history the steps before it left behind.
 */
export const runScenario = (scenario: Scenario): ScenarioResult => {
  let hasQuoted = false;
  const results = scenario.steps.map((step) => {
    const result = runStep(step, {
      customer: scenario.customer,
      isFollowUpContract: hasQuoted,
    });
    if (step.op === "quote") hasQuoted = true;
    return result;
  });
  return { results };
};
